import{_ as r}from"./chunks/ArticleMetadata.CJLh0kTh.js";import{_ as t,E as o,c as d,o as e,ab as p,I as c,w as h,b,e as m}from"./chunks/framework.DATyEJnP.js";import"./chunks/theme.mcdYQple.js";const C=JSON.parse('{"title":"虚拟机(Homestead Vagrant)","description":"","frontmatter":{"title":"虚拟机(Homestead Vagrant) ","urlname":"QXs8drrh5o9iIrx2blvcqeT3nNh","date":"2025-04-03 00:15:43","updated":"2025-04-04 20:54:05"},"headers":[],"relativePath":"feishu/docs/集成文档/QXs8drrh5o9iIrx2blvcqeT3nNh.md","filePath":"feishu/docs/集成文档/QXs8drrh5o9iIrx2blvcqeT3nNh.md","lastUpdated":1744216491000}'),u={name:"feishu/docs/集成文档/QXs8drrh5o9iIrx2blvcqeT3nNh.md"},g=p(`<h2 id="_1-virtualbox" tabindex="-1">1，VirtualBox <a class="header-anchor" href="#_1-virtualbox" aria-label="Permalink to &quot;1，VirtualBox&quot;">​</a></h2><p>VirtualBox 是 Oracle 公司的开源虚拟机软件。VirtualBox 号称是最强的免费虚拟机软件，它不仅功能齐全，而且性能也很优异！VirtualBox 支持大部分流行的系统，如：Mac, Windows, Linux 等。</p><p><a href="https://www.virtualbox.org/wiki/Downloads" target="_blank" rel="noreferrer">https://www.virtualbox.org/wiki/Downloads</a></p><p>链接: <a href="https://pan.baidu.com/s/15nYWNHuHHYEWoVGwFgTF8Q" target="_blank" rel="noreferrer">https://pan.baidu.com/s/15nYWNHuHHYEWoVGwFgTF8Q</a> 提取码: rk4p</p><h2 id="_2-vagrant-统一开发环境" tabindex="-1">2，Vagrant 统一开发环境 <a class="header-anchor" href="#_2-vagrant-统一开发环境" aria-label="Permalink to &quot;2，Vagrant 统一开发环境&quot;">​</a></h2><p>Vagrant 是一个用于创建和部署虚拟化开发环境的工具，其依赖于 VirtualBox 虚拟机，致力于帮助开发者快速构建一个环境统一的虚拟系统。Vagrant 最强大的地方是在于它在构建虚拟系统时的快捷简便，使开发者可以在短短几分钟内完成一个虚拟系统的删除与构建。</p><p><a href="https://developer.hashicorp.com/vagrant/install?product_intent=vagrant" target="_blank" rel="noreferrer">https://developer.hashicorp.com/vagrant/install?product_intent=vagrant</a></p><p>链接: <a href="https://pan.baidu.com/s/15nYWNHuHHYEWoVGwFgTF8Q" target="_blank" rel="noreferrer">https://pan.baidu.com/s/15nYWNHuHHYEWoVGwFgTF8Q</a> 提取码: rk4p</p><h2 id="_3-homestead" tabindex="-1">3，homestead <a class="header-anchor" href="#_3-homestead" aria-label="Permalink to &quot;3，homestead&quot;">​</a></h2><p>Homestead 包含了两个东西：</p><ul><li><p>Homestead 管理脚本；</p></li><li><p>Homestead Box 虚拟机盒子。</p></li></ul><h3 id="homestead-管理脚本" tabindex="-1">Homestead 管理脚本 <a class="header-anchor" href="#homestead-管理脚本" aria-label="Permalink to &quot;Homestead 管理脚本&quot;">​</a></h3><p><a href="https://github.com/laravel/homestead" target="_blank" rel="noreferrer">Homestead</a> 脚本使用 Ruby 和 Shell 脚本编写而成。原理是对 Vagrantfile 文件做定制。</p><p><a href="https://portal.cloud.hashicorp.com/vagrant/discover/laravel/homestead" target="_blank" rel="noreferrer">https://portal.cloud.hashicorp.com/vagrant/discover/laravel/homestead</a></p><h3 id="homestead-box-虚拟机盒子" tabindex="-1">Homestead Box 虚拟机盒子 <a class="header-anchor" href="#homestead-box-虚拟机盒子" aria-label="Permalink to &quot;Homestead Box 虚拟机盒子&quot;">​</a></h3><p>homestead.box 虚拟机盒子是提前打包好的 Vagrant Box 虚拟机盒子，里面预装了 Nginx Web 服务器、PHP 7、MySQL、Postgres、Redis、Memcached、Node，以及所有你在使用 Laravel 开发时所需要用到的各种软件。</p><h3 id="定制版本的虚拟机盒子" tabindex="-1">定制版本的虚拟机盒子 <a class="header-anchor" href="#定制版本的虚拟机盒子" aria-label="Permalink to &quot;定制版本的虚拟机盒子&quot;">​</a></h3><ol><li>下载和导入 Homestead Box 虚拟机盒子；</li></ol><p>附：百度盘下载链接: <a href="https://pan.baidu.com/s/1LCiwc9ZP9kKdEyMUSabugg" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1LCiwc9ZP9kKdEyMUSabugg</a> 提取码: idk9</p><p>此目录下包含两个文件：</p><ul><li><p>virtualbox.box（教程定制化过的 Homestead 盒子）</p></li><li><p>metadata.json（盒子的导入配置文件）</p></li></ul><ol><li><p>安装 Git ，为下载 Homestead 管理脚本做准备；</p></li><li><p>使用 Git 下载 Homestead 管理脚本；</p></li></ol><p>定制版有以下优势：</p><ul><li><p>从国内 coding.net 网站下载，下载速度会比 <a href="https://github.com/laravel/homestead" target="_blank" rel="noreferrer">官方</a> 更快；</p></li><li><p>对脚本进行修改，移除了每一次 <code>provision</code> 时 <code>composer self-update</code> 的卡顿。</p></li><li></li></ul><p>添加虚拟机基础镜像（Box）的命令</p><p>vagrant box add 命令</p><p>1，下载或复制 Box 文件 ：</p><ul><li><p>如果指定了远程 URL 或 Vagrant Cloud 上的 Box 名称，Vagrant 会从远程服务器下载 Box 文件</p></li><li><p>如果指定了本地文件路径，Vagrant 会复制该文件</p></li><li><p>验证 Box 完整性 ：</p></li></ul><p>2，检查 Box 文件的完整性，确保下载或复制过程中没有损坏</p><ul><li>验证 Box 的格式是否符合 Vagrant 的要求</li></ul><p>3 添加到 Box 仓库 ：</p><ul><li><p>将 Box 添加到 Vagrant 的本地 Box 仓库中</p></li><li><p>在 Windows 系统中，Box 仓库通常位于 C:\\Users\\用户名.vagrant.d\\boxes 目录</p></li></ul><p>4，创建元数据 ：</p><ul><li><p>为 Box 创建元数据，包括名称、版本、提供商等信息</p></li><li><p>这些元数据用于后续的 Box 管理和虚拟机创建</p></li></ul><div class="language-power vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">power</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>vagrant box add metadata.json</span></span>
<span class="line"><span>vagrant box list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>git clone https://gitee.com/summerblue/homestead.git Homestead</span></span>
<span class="line"><span>git clone https://github.com/laravel/homestead.git Homestead</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd Homestead</span></span>
<span class="line"><span>git checkout v13.2.1 #将当前的工作目录切换到标签为 &quot;v13.2.1&quot; 的版本。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>init.bat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>#init.bat生成3个文件</p><ul><li><p>Homestead.yaml - 主要配置信息文件，我们可以在此文件中配置 Homestead 的站点和数据库等信息；</p></li><li><p>after.sh - 每一次 Homestead 盒子重置后（provision）会调用的 shell 脚本文件；</p></li><li><p>aliases - 每一次 Homestead 盒子重置后（provision），会被替换至虚拟机的 ~/.bash_aliases 文件中，aliases 里可以放一些快捷命令的定义。</p></li></ul><div class="language-power vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">power</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>explorer . #用文件夹打开当前命令行所在目录：</span></span>
<span class="line"><span>code . ~/Homestead/Homestead.yaml #运行下面命令快速打开 Homestead.yaml 文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-power vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">power</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>ssh-keygen -t rsa -C &quot;1064041207@qq.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="运行-vagrant" tabindex="-1">运行 Vagrant <a class="header-anchor" href="#运行-vagrant" aria-label="Permalink to &quot;运行 Vagrant&quot;">​</a></h3><p>完成了 Homestead 的配置，接下来我们要开始启动虚拟机了。</p><p>在命令中输入 vagrant，能看到 Vagrant 为我们提供了一些便利的命令行，下面简单介绍一下 Vagrant 常用的一些命令行的使用：</p><p>vagrant init 初始化 vagrant</p><p>vagrant up 启动 vagrant</p><p>vagrant halt 关闭 vagrant</p><p>vagrant ssh 通过 SSH 登录 vagrant（需要先启动 vagrant）</p><p>vagrant provision 重新应用更改 vagrant 配置</p><p>vagrant destroy 删除 vagrant</p><p>第一次启动时，Vagrant 会做以下这几件事情：</p><ul><li><p>以导入的 Homestead 虚拟机盒子为模板，新建一台虚拟机；</p></li><li><p>并按照 Homestead.yaml 里的配置信息，对这台新建的虚拟机进行配置；配置完成后启动虚拟机。</p></li></ul><div class="language-power vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">power</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>#其他命令</span></span>
<span class="line"><span>vagrant status #检查虚拟机是否正在运行：</span></span>
<span class="line"><span>vagrant ssh-config     #重新初始化 SSH 配置</span></span>
<span class="line"><span>vagrant ssh -- -v #使用详细模式尝试连接</span></span>
<span class="line"><span>vagrant reload #尝试重新加载虚拟机</span></span>
<span class="line"><span>vagrant reload --provision #尝试重新加载虚拟机，并执行所有的配置脚本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="language-undefined vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">undefined</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>## vagrant reload</span></span>
<span class="line"><span>vagrant reload 命令会重启虚拟机并重新加载 Vagrantfile 的配置，但不会重新执行配置脚本。这意味着：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 虚拟机会关闭并重新启动</span></span>
<span class="line"><span>- 会应用 Vagrantfile 中的新配置（如内存、CPU 设置等）</span></span>
<span class="line"><span>- 不会重新执行配置脚本（如安装软件、复制文件等）</span></span>
<span class="line"><span>这个命令适用于您只修改了虚拟机的基本配置（如网络设置、资源分配等）的情况。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## vagrant reload --provision</span></span>
<span class="line"><span>vagrant reload --provision 命令不仅会重启虚拟机并重新加载配置，还会重新执行所有的配置脚本。这意味着：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 虚拟机会关闭并重新启动</span></span>
<span class="line"><span>- 会应用 Vagrantfile 中的新配置</span></span>
<span class="line"><span>- 会重新执行所有配置脚本，包括：</span></span>
<span class="line"><span>  - 复制 SSH 密钥</span></span>
<span class="line"><span>  - 设置共享文件夹</span></span>
<span class="line"><span>  - 安装软件包</span></span>
<span class="line"><span>  - 配置服务等</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h1 id="homestead-rb-文件的作用与创建多个虚拟机的配置方法" tabindex="-1">homestead.rb 文件的作用与创建多个虚拟机的配置方法 <a class="header-anchor" href="#homestead-rb-文件的作用与创建多个虚拟机的配置方法" aria-label="Permalink to &quot;homestead.rb 文件的作用与创建多个虚拟机的配置方法&quot;">​</a></h1>`,53),v=p('<p>homestead.rb 文件是 Laravel Homestead 的核心配置脚本，它定义了 Homestead 类，负责根据 Homestead.yaml 或 Homestead.json 文件中的设置来配置 Vagrant 虚拟机。这个文件主要功能包括：</p><ol><li><p>设置虚拟机的基本属性（名称、内存、CPU等）</p></li><li><p>配置网络设置（IP地址、端口转发等）</p></li><li><p>设置共享文件夹</p></li><li><p>配置数据库</p></li><li><p>设置网站和域名</p></li><li><p>安装和配置各种功能和服务</p></li></ol><h2 id="虚拟机网络" tabindex="-1">虚拟机网络 <a class="header-anchor" href="#虚拟机网络" aria-label="Permalink to &quot;虚拟机网络&quot;">​</a></h2><div class="language-power vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">power</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>vagrant ssh -c &quot;ip addr show&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Homestead 虚拟机有多个网络接口：</p><ul><li><p>eth1 接口的 IP 是 192.168.56.58</p></li><li><p>docker0 接口的 IP 是 172.17.0.1</p></li></ul>',6);function k(a,f,_,x,H,V){const l=r,i=o("ClientOnly");return e(),d("div",null,[g,c(i,null,{default:h(()=>{var s,n;return[(((s=a.$frontmatter)==null?void 0:s.aside)??!0)&&(((n=a.$frontmatter)==null?void 0:n.showArticleMetadata)??!0)?(e(),b(l,{key:0,article:a.$frontmatter},null,8,["article"])):m("",!0)]}),_:1}),v])}const B=t(u,[["render",k]]);export{C as __pageData,B as default};
